  ["b204f194d7fbd681"] = { "Non sono bellissimi questi motivi? Ognuno parla con la sua voce.", "." },
  ["b2067e9b19c108b9"] = { "Voglio un attacco chirurgico, Slidore. Copri la strada di fuoco!", "." },
  ["b207e4a1cea0a0c1"] = { "che preda facile.", "." },
  ["b20935dcae1131c1"] = { "Ho ricevuto un aggiornamento proprio un attimo fa. Pare che, dei $2061w pezzi di Cuoio Leggero necessari, ne abbiamo $2060w. Quanto agli altri, il rapporto indica che abbiamo raccolto $2063w pezzi di Cuoio Medio su $2064w, e $2069w su $2071w della nostra quota di Cuoio Spesso.", "." },
  ["b20ad28fd1e5f24d"] = { "I segni su questa tavoletta mostrano antichi diagrammi e recano terribili parole di potere, ma il loro significato ti è incomprensibile.", "." },
  ["b214108108cd3871"] = { "Siamo uniti nella causa, {race}. Un male antico minaccia di estinguere ogni forma di vita su Kalimdor e di consumare il mondo con la sua depravazione... Odia tutto ciò che è nato dai grandi Plasmatori: gli eterni Titani.\n\nSiamo la prima e l'ultima linea di difesa contro le Armate di C'thun. Se non ci solleviamo a colpire il nemico, il nemico ci distruggerà di certo.\n\nLo sforzo bellico ha bisogno di te!", "." },
  ["b21585ebb764ad48"] = { "Cosa credi che potrei insegnarti? Roxxik farebbe un lavoro molto migliore. Lo trovi a Orgrimmar. Ora vattene!", "." },
  ["b21db46ea478a3cc"] = { "Cosa ci fa un elfo come te in una grotta come questa?", "." },
  ["b2276c81ee78e3ee"] = { "Servito!", "." },
  ["b227e05612c466a7"] = { "Dov'è l'anziano Morndeep?", "." },
  ["b22bc7189e3b55ee"] = { "Sei <uno/una> <stolto/stolta>, e presto perderai la vita. No?", "." },
  ["b2301c8c950c5fc0"] = { "PER LA FORZA DI KALIMDOR!", "." },
  ["b23449bccc0c0143"] = { "Chi è <questo/questa> {class} che si presenta davanti alla Corte di Lakshire nel Regno di ⟦Stormwind=Roccavento⟧? Dichiara cosa ti porta in questo borgo, {race}. La minaccia degli orchi sul Regno è troppo grande per sprecare tempo in chiacchiere oziose.", "." },
  ["b234e47b72bec3ea"] = { "Molto bene, {name}. Troverai Grizzle Halfmane nel Royal Quarter di ⟦Undercity=Sepulcra⟧. Che tu possa trovare grande onore nella ⟦Alterac Valley=Valle d'Alterac⟧.", "." },
  ["b23b724c21623359"] = { "In attesa di ordini dai miei superiori!", "." },
  ["b23b725921623366"] = { "In attesa di ordini dai miei superiori.", "." },
  ["b23d49a4f6472a67"] = { "Dove altro stiamo combattendo il Flagello?", "." },
  ["b244901a579bfb26"] = { "Non ascoltare i cuori del mondo: la risposta sta dentro di te. Tu conosci la verità.", "." },
  ["b244a94ebe0698ab"] = { "Uno splendido Winter's Veil a te... ehm... <piccolo/piccola> <bambino/bambina>. I bambini buoni ricevono speciali, ehm, sconti da qualsiasi venditore della Masseria Buongusto. Gnam.", "." },
  ["b2513485456e30dd"] = { "Altri Totem Truce in arrivo da questa parte!", "." },
  ["b25becdacf7f221d"] = { "Le unità campione stanno entrando in battaglia!", "." },
  ["b2616af3e0df71f3"] = { "Orchi? ⟦Badlands=Maleterre⟧? Sono invulnerabile!", "." },
  ["b264f7c0d259f69b"] = { "Osi profanare il ⟦Frostmane Hold=Covo dei Mantogelido⟧, {race}. Preparati a morire!", "." },
  ["b265b6ae9e9dadff"] = { "{name}! Sei <tornato/tornata>! E appena in tempo!", "." },
  ["b26678fe3a7a13c3"] = { "Scuoiatura? L'unica cosa che sembri capace di scuoiare è il tuo ginocchio! Ah! Perché non vai da Balthus Stoneflayer, così ti insegna a scuoiare gli animali come si deve? Lo trovi da Finespindle's Leather Goods, sul lato nord della ⟦Great Forge=Grande Forgia⟧.", "." },
  ["b26ce58a29567893"] = { "Be', per fondare una gilda ti servono i documenti, e Jondor Steelbrow può aiutarti ad avviare la pratica. Lo trovi al Visitor's Center di ⟦Ironforge=Forgiardente⟧, quando vuoi cominciare.", "." },
  ["b27a12ca5eac02a2"] = { "Non c'è via d'uscita.", "." },
  ["b27b004e0924c762"] = { "Un debole sussurro giunge dall'interno della pietra...\n\nSalute, <piccolo/piccola>. Hai notizie per il Templare?", "." },
  ["b280f0fca835d403"] = { "⟦Rogues' Quarter=Quartiere dei Ladri⟧ attaccato dal Flagello! Aiuto!", "." },
  ["b28b36e8b95a699a"] = { "Buone notizie, {name}. Molthor in questi giorni canta le tue lodi. Dice che stai diventando <un/una> ver<o/a> <eroe/eroina> di Zandalar.\n\nDice anche che Maywiki deve lucidare ancora il tuo globo! Dammelo qua, così Maywiki può schiarire la visione.", "." },
  ["b2923cdd41ed192d"] = { "Inspira a fondo il profumo del fiore del canto.", "." },
  ["b297a32b0ddc1e40"] = { "Ben <trovato/trovata>, {class}. Se sei qui per affari, prenditi una birra e facciamo due chiacchiere.", "." },
  ["b2a61f0ef906f540"] = { "Cinque e cinque anni, e lui la cerca ancora, benché non fosse una bellezza, e molte dame avrebbero preso il suo posto.", "." },
  ["b2aea9ea853107fa"] = { "Puoi ringraziarmi quando vuoi per averti reso la vita più interessante.", "." },
  ["b2c0a1099df3a769"] = { "Hai il male tra le mani, <stolto/stolta>! PENTITI!", "." },
  ["b2c3d1286eca47bd"] = { "Posso insegnarti a creare armature di cuoio raffinate, se ne hai l'attitudine.", "." },
  ["b2c947b43400c3c8"] = { "Dubito molto che abbia qualcosa da dire, <straniero/straniera>...", "." },
  ["b2cb4eca40bbf7b2"] = { "La ⟦Irondeep Mine=Miniera di Ferrofondo⟧ appartiene all'⟦Alliance=Alleanza⟧.", "." },
  ["b2d8bfeac47eeb36"] = { "Laurna Morninglight offre cure a chi vive nei dintorni di Dolanaar. Forse potrebbe insegnarti le vie del sacerdote.", "." },
  ["b2db422efb9bf549"] = { "Sembra che resti solo un altro giorno di pesca prima che tutto 'sto materiale bellico venga spedito nel deserto di ⟦Silithus=Silitus⟧, <amico/amica>. Poi lo prepareranno tutto, e qualcuno dovrà suonare quel gong giù a sud della ⟦Cenarion Hold=Fortezza Cenariana⟧ per aprire i cancelli e cominciare la guerra.", "." },
  ["b2dfbc391e63f556"] = { "Spiedini di ratto! Venite a prendere i vostri gustosi spiedini di ratto! Finché ce ne sono!", "." },
  ["b2e967f695dc01ba"] = { "Voglio comprendere l'importanza della forza del cuore.", "." },
  ["b2e9e1a2b2ce2ec0"] = { "La tribù Scheggiadura ti condurrà alla rovina!", "." },
  ["b2ede4467fcf0668"] = { "Dovete continuare! La loro determinazione vacilla. Bevete dal mio potere e rinnovatevi ancora una volta!", "." },
  ["b2f4edeed99afd0b"] = { "Sai abbastanza da essere <pericoloso/pericolosa>, ma secondo me hai ancora bisogno di addestramento, {name}.", "." },
  ["b2fd9df242a87e34"] = { "Faresti meglio ad andartene, <ragazzo/ragazza>. Il mio animale qui ha fame, e gli piace il tuo odore.", "." },
